    <title>Support Contact Form</title>
    <meta
      name="description"
      content="Contact support with your full name, email address, and optional phone number."
    />
    <style>
      :root {
        color-scheme: light;
        --bg: #f4f7fb;
        --surface: #ffffff;
        --surface-alt: #f8fafc;
        --text: #132033;
        --muted: #53657f;
        --border: #cfd8e6;
        --border-strong: #94a3b8;
        --primary: #2457d6;
        --primary-hover: #1e49b0;
        --danger: #b42318;
        --danger-bg: #fef3f2;
        --shadow: 0 24px 60px #1020331a;
        --radius: 20px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #dbe9ff 0, transparent 30%),
          linear-gradient(180deg, #f7faff 0%, var(--bg) 100%);
      }

      a {
        color: var(--primary);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--surface);
        color: var(--text);
        text-decoration: none;
        transform: translateY(-200%);
        transition: transform 0.2s ease;
        box-shadow: var(--shadow);
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(100%, 72rem);
        margin: 0 auto;
        padding: 1.25rem;
      }

      header {
        padding: 1rem 0 1.5rem;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      .brand-mark {
        display: inline-grid;
        place-items: center;
        width: 2.5rem;
        height: 2.5rem;
        border-radius: 0.9rem;
        background: linear-gradient(135deg, #2f6ef0, #7c3aed);
        color: #fff;
        box-shadow: 0 12px 30px #295fe022;
      }

      main {
        padding: 1rem 0 2rem;
      }

      .hero {
        max-width: 42rem;
        margin-bottom: 1.5rem;
      }

      h1 {
        margin: 0 0 0.5rem;
        font-size: clamp(2rem, 4vw, 3.5rem);
        line-height: 1.05;
        letter-spacing: -0.03em;
      }

      .lead {
        margin: 0;
        font-size: 1.05rem;
        color: var(--muted);
      }

      .card {
        max-width: 44rem;
        padding: clamp(1.25rem, 2vw, 2rem);
        border: 1px solid #d8e2ef;
        border-radius: var(--radius);
        background: color-mix(in srgb, var(--surface) 96%, transparent);
        box-shadow: var(--shadow);
        backdrop-filter: blur(10px);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.45rem;
      }

      label {
        font-weight: 600;
      }

      .required {
        color: var(--danger);
      }

      input,
      button {
        font: inherit;
      }

      input {
        width: 100%;
        min-width: 0;
        padding: 0.95rem 1rem;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        background: var(--surface);
        color: var(--text);
        transition:
          border-color 0.15s ease,
          box-shadow 0.15s ease,
          transform 0.15s ease;
      }

      input::placeholder {
        color: #8a97aa;
      }

      input:hover {
        border-color: var(--border-strong);
      }

      input:focus {
        outline: 3px solid #cfe0ff;
        outline-offset: 2px;
        border-color: var(--primary);
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        background: var(--danger-bg);
      }

      .help-text {
        margin: 0;
        font-size: 0.92rem;
        color: var(--muted);
      }

      .error-text {
        min-height: 1.25rem;
        margin: 0;
        font-size: 0.92rem;
        color: var(--danger);
      }

      .error-text:empty {
        display: block;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
        flex-wrap: wrap;
        margin-top: 0.25rem;
      }

      .submit {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.35rem;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--primary), #6b4cf5);
        box-shadow: 0 16px 30px #2457d633;
        cursor: pointer;
      }

      .submit:hover {
        background: linear-gradient(135deg, var(--primary-hover), #5d3fe7);
      }

      .submit:focus {
        outline: 3px solid #cfe0ff;
        outline-offset: 3px;
      }

      .status {
        margin: 0;
        min-height: 1.5rem;
        color: var(--muted);
      }

      .status.is-success {
        color: #087443;
      }

      .fine-print {
        margin: 0;
        font-size: 0.92rem;
        color: var(--muted);
      }

      @media (min-width: 48rem) {
        .grid-two {
          display: grid;
          grid-template-columns: repeat(2, minmax(0, 1fr));
          gap: 1rem;
        }
      }

      @media (forced-colors: active) {
        :root {
          --bg: Canvas;
          --surface: Canvas;
          --surface-alt: Canvas;
          --text: CanvasText;
          --muted: CanvasText;
          --border: ButtonBorder;
          --border-strong: ButtonBorder;
          --primary: LinkText;
          --primary-hover: LinkText;
          --danger: ButtonText;
          --danger-bg: Canvas;
        }

        body,
        .card,
        input,
        .submit,
        .skip-link {
          forced-color-adjust: auto;
        }

        .card {
          box-shadow: none;
        }

        .submit {
          border: 1px solid ButtonBorder;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
        successMessage: "",
      };

      const fieldConfig = {
        fullName: {
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Morgan",
        },
        email: {
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@company.com",
        },
        phone: {
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          helperText: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
        },
      };

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getFieldError(name, value) {
        const trimmed = value.trim();

        if (name === "fullName") {
          if (!trimmed) return "Full name is required.";
          if (trimmed.length < 2) return "Enter your full name.";
          return "";
        }

        if (name === "email") {
          if (!trimmed) return "Email address is required.";
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
            return "Enter a valid email address.";
          }
          return "";
        }

        if (name === "phone") {
          if (!trimmed) return "";
          if (!/^\+?[0-9\s().-]{7,}$/.test(trimmed)) {
            return "Enter a valid phone number, or leave it blank.";
          }
          return "";
        }

        return "";
      }

      function getErrors(values) {
        return {
          fullName: getFieldError("fullName", values.fullName),
          email: getFieldError("email", values.email),
          phone: getFieldError("phone", values.phone),
        };
      }

      function fieldId(name) {
        return `field-${name}`;
      }

      function errorId(name) {
        return `error-${name}`;
      }

      function helpId(name) {
        return `help-${name}`;
      }

      function Field(name, value, error, touched) {
        const config = fieldConfig[name];
        const describedBy = [config.helperText ? helpId(name) : null, error ? errorId(name) : null]
          .filter(Boolean)
          .join(" ");
        const showError = touched || state.submitted;

        return `
          <div class="form-field">
            <label for="${fieldId(name)}">
              ${escapeHtml(config.label)}
              ${config.required ? '<span class="required" aria-hidden="true"> *</span>' : ""}
            </label>
            <input
              id="${fieldId(name)}"
              name="${name}"
              type="${config.type}"
              value="${escapeHtml(value)}"
              ${config.placeholder ? `placeholder="${escapeHtml(config.placeholder)}"` : ""}
              ${config.autocomplete ? `autocomplete="${config.autocomplete}"` : ""}
              ${config.required ? "required" : ""}
              ${config.type === "tel" ? 'inputmode="tel"' : ""}
              aria-describedby="${describedBy}"
              ${error && showError ? 'aria-invalid="true"' : ""}
            />
            ${config.helperText ? `<p class="help-text" id="${helpId(name)}">${escapeHtml(config.helperText)}</p>` : ""}
            <p class="error-text" id="${errorId(name)}" aria-live="polite">${showError && error ? escapeHtml(error) : ""}</p>
          </div>
        `;
      }

      function SupportForm() {
        const errors = getErrors(state.values);

        return `
          <main id="main-content" class="page-shell">
            <div class="hero">
              <p class="brand" aria-label="Support">
                <span class="brand-mark" aria-hidden="true">?</span>
                Support
              </p>
              <h1>Contact our support team</h1>
              <p class="lead">
                Send us your details and we&apos;ll follow up with the next steps.
              </p>
            </div>

            <section class="card" aria-labelledby="contact-form-heading">
              <h2 id="contact-form-heading" class="sr-only" hidden>Contact form</h2>
              <p class="status ${state.successMessage ? "is-success" : ""}" aria-live="polite">
                ${escapeHtml(state.successMessage)}
              </p>
              <form id="contact-form" novalidate>
                <div class="grid-two">
                  ${Field("fullName", state.values.fullName, errors.fullName, state.touched.fullName)}
                  ${Field("email", state.values.email, errors.email, state.touched.email)}
                </div>
                ${Field("phone", state.values.phone, errors.phone, state.touched.phone)}
                <div class="actions">
                  <button class="submit" type="submit">Submit request</button>
                  <p class="fine-print">We only use your details to respond to this request.</p>
                </div>
              </form>
            </section>
          </main>
        `;
      }

      function App() {
        return `
          <div>
            <header class="page-shell">
              <div class="brand" aria-hidden="true">
                <span class="brand-mark">?</span>
                Support
              </div>
            </header>
            ${SupportForm()}
          </div>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        bindForm();
      }

      function updateField(name, value) {
        state.values[name] = value;
        render();
        const input = document.getElementById(fieldId(name));
        if (input) input.focus({ preventScroll: true });
        input?.setSelectionRange(value.length, value.length);
      }

      function bindForm() {
        const form = document.getElementById("contact-form");
        if (!form) return;

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.touched = {
            fullName: true,
            email: true,
            phone: true,
          };
          state.submitted = true;
          const errors = getErrors(state.values);
          const firstInvalid = ["fullName", "email", "phone"].find((name) => errors[name]);

          if (firstInvalid) {
            state.successMessage = "";
            render();
            document.getElementById(fieldId(firstInvalid))?.focus();
            return;
          }

          state.successMessage = "Thanks. Your request is ready to send.";
          render();
          form.reset();
          state.values = { fullName: "", email: "", phone: "" };
          state.touched = { fullName: false, email: false, phone: false };
        });

        ["fullName", "email", "phone"].forEach((name) => {
          const input = document.getElementById(fieldId(name));
          input?.addEventListener("input", (event) => {
            state.values[name] = event.target.value;
            state.successMessage = "";
            render();
          });
          input?.addEventListener("blur", () => {
            state.touched[name] = true;
            render();
          });
        });
      }

      render();
    </script>
