  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>

    <script>
      const state = {
        values: {
          fullName: "",
          email: "",
          phone: "",
        },
        touched: {
          fullName: false,
          email: false,
          phone: false,
        },
        submitted: false,
        successMessage: "",
      };

      const fieldConfig = {
        fullName: {
          label: "Full name",
          type: "text",
          autocomplete: "name",
          required: true,
          placeholder: "Alex Morgan",
        },
        email: {
          label: "Email address",
          type: "email",
          autocomplete: "email",
          required: true,
          placeholder: "alex@company.com",
        },
        phone: {
          label: "Phone number",
          type: "tel",
          autocomplete: "tel",
          required: false,
          placeholder: "+1 555 123 4567",
          helperText: "Optional. Use a format like +1 555 123 4567 or 555-123-4567.",
        },
      };

      function escapeHtml(value) {
        return String(value)
          .replaceAll("&", "&amp;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;")
          .replaceAll('"', "&quot;")
          .replaceAll("'", "&#39;");
      }

      function getFieldError(name, value) {
        const trimmed = value.trim();

        if (name === "fullName") {
          if (!trimmed) return "Full name is required.";
          if (trimmed.length < 2) return "Enter your full name.";
          return "";
        }

        if (name === "email") {
          if (!trimmed) return "Email address is required.";
          if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
            return "Enter a valid email address.";
          }
          return "";
        }

        if (name === "phone") {
          if (!trimmed) return "";
          if (!/^\+?[0-9\s().-]{7,}$/.test(trimmed)) {
            return "Enter a valid phone number, or leave it blank.";
          }
          return "";
        }

        return "";
      }

      function getErrors(values) {
        return {
          fullName: getFieldError("fullName", values.fullName),
          email: getFieldError("email", values.email),
          phone: getFieldError("phone", values.phone),
        };
      }

      function fieldId(name) {
        return `field-${name}`;
      }

      function errorId(name) {
        return `error-${name}`;
      }

      function helpId(name) {
        return `help-${name}`;
      }

      function Field(name, value, error, touched) {
        const config = fieldConfig[name];
        const describedBy = [config.helperText ? helpId(name) : null, errorId(name)]
          .filter(Boolean)
          .join(" ");
        const showError = touched || state.submitted;

        return `
          <div class="form-field">
            <label for="${fieldId(name)}">
              ${escapeHtml(config.label)}
              ${config.required ? '<span class="required" aria-hidden="true"> *</span>' : ""}
            </label>
            <input
              id="${fieldId(name)}"
              name="${name}"
              type="${config.type}"
              value="${escapeHtml(value)}"
              ${config.placeholder ? `placeholder="${escapeHtml(config.placeholder)}"` : ""}
              ${config.autocomplete ? `autocomplete="${config.autocomplete}"` : ""}
              ${config.required ? "required" : ""}
              ${config.type === "tel" ? 'inputmode="tel"' : ""}
              aria-describedby="${describedBy}"
              ${error && showError ? 'aria-invalid="true"' : ""}
            />
            ${config.helperText ? `<p class="help-text" id="${helpId(name)}">${escapeHtml(config.helperText)}</p>` : ""}
            <p class="error-text" id="${errorId(name)}" aria-live="polite">${showError && error ? escapeHtml(error) : ""}</p>
          </div>
        `;
      }

      function SupportForm() {
        const errors = getErrors(state.values);

        return `
          <main id="main-content" class="page-shell">
            <div class="hero">
              <p class="brand" aria-label="Support">
                <span class="brand-mark" aria-hidden="true">?</span>
                Support
              </p>
              <h1>Contact our support team</h1>
              <p class="lead">
                Send us your details and we&apos;ll follow up with the next steps.
              </p>
            </div>

            <section class="card" aria-labelledby="contact-form-heading">
              <h2 id="contact-form-heading" hidden>Contact form</h2>
              <p class="status ${state.successMessage ? "is-success" : ""}" aria-live="polite">
                ${escapeHtml(state.successMessage)}
              </p>
              <form id="contact-form" novalidate>
                <div class="grid-two">
                  ${Field("fullName", state.values.fullName, errors.fullName, state.touched.fullName)}
                  ${Field("email", state.values.email, errors.email, state.touched.email)}
                </div>
                ${Field("phone", state.values.phone, errors.phone, state.touched.phone)}
                <div class="actions">
                  <button class="submit" type="submit">Submit request</button>
                  <p class="fine-print">We only use your details to respond to this request.</p>
                </div>
              </form>
            </section>
          </main>
        `;
      }

      function App() {
        return `
          <div>
            <header class="page-shell">
              <div class="brand" aria-hidden="true">
                <span class="brand-mark">?</span>
                Support
              </div>
            </header>
            ${SupportForm()}
          </div>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = App();
        bindForm();
      }

      function syncField(name) {
        const input = document.getElementById(fieldId(name));
        const errorText = document.getElementById(errorId(name));
        if (!input || !errorText) return;

        const error = getFieldError(name, state.values[name]);
        const shouldShowError = state.touched[name] || state.submitted;

        if (error && shouldShowError) {
          input.setAttribute("aria-invalid", "true");
          errorText.textContent = error;
        } else {
          input.removeAttribute("aria-invalid");
          errorText.textContent = "";
        }
      }

      function syncFormStatus() {
        ["fullName", "email", "phone"].forEach(syncField);

        const status = document.querySelector(".status");
        if (status) {
          status.textContent = state.successMessage;
          status.classList.toggle("is-success", Boolean(state.successMessage));
        }
      }

      function bindForm() {
        const form = document.getElementById("contact-form");
        if (!form) return;

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          state.touched = {
            fullName: true,
            email: true,
            phone: true,
          };
          state.submitted = true;
          const errors = getErrors(state.values);
          const firstInvalid = ["fullName", "email", "phone"].find((name) => errors[name]);

          if (firstInvalid) {
            state.successMessage = "";
            syncFormStatus();
            document.getElementById(fieldId(firstInvalid))?.focus();
            return;
          }

          state.successMessage = "Thanks. Your request is ready to send.";
          syncFormStatus();
          form.reset();
          state.values = { fullName: "", email: "", phone: "" };
          state.touched = { fullName: false, email: false, phone: false };
          syncFormStatus();
        });

        ["fullName", "email", "phone"].forEach((name) => {
          const input = document.getElementById(fieldId(name));
          input?.addEventListener("input", (event) => {
            state.values[name] = event.target.value;
            state.successMessage = "";
            syncField(name);
            const status = document.querySelector(".status");
            if (status) status.textContent = "";
          });
          input?.addEventListener("blur", () => {
            state.touched[name] = true;
            syncField(name);
          });
        });

        syncFormStatus();
      }

      render();
    </script>
  </body>
